{
  "contract": "NeoCypherpunk",
  "closure": {
    "site_function": "feeClaim",
    "site_call": ".call",
    "functions": [
      "transfer",
      "transferFrom"
    ],
    "justification": "These functions can be called during the callback window and affect the balance."
  },
  "protocol": {
    "during_phase": "exposed",
    "allowed_callbacks": [
      "transfer",
      "transferFrom"
    ],
    "nesting_bound": {
      "transfer": 1,
      "transferFrom": 1
    }
  },
  "phases": {
    "function": "feeClaim",
    "pre": {
      "name": "pre",
      "from_marker": "start",
      "to_marker": "before_call"
    },
    "exposed": {
      "name": "exposed",
      "from_marker": "before_call",
      "to_marker": "after_call"
    },
    "post": {
      "name": "post",
      "from_marker": "after_call",
      "to_marker": "end"
    },
    "linearization_point": "after_call"
  },
  "ghost_state": [
    {
      "name": "inFlight",
      "sol_type": "uint256",
      "meaning": "Amount of pending marketing fees in-flight during callback",
      "backed_by_storage": false
    }
  ],
  "exposure_invariant": {
    "formula": "pendingmarketingFees == snapPre + inFlight",
    "stable_formula": "pendingmarketingFees == snapPre",
    "kind": "conserve"
  },
  "composition": {
    "target_property": "pendingmarketingFees <= _balances[address(this)]",
    "rule": "Ensure pending marketing fees do not exceed contract's balance"
  }
}
